import net.jcip.annotations.GuardedBy;
import java.util.concurrent.atomic.AtomicBoolean;
import org.springframework.beans.factory.annotation.Autowired;
class Good3 {
    @GuardedBy("this")
    private String txt;
    private final AtomicBoolean ab = new AtomicBoolean();

    public void modifyText() {
        synchronized(this) {
            txt += "-appended";
        }
    }

    public void consumeText() {
        synchronized(this) {
            ab.set(txt.equals("bla"));
        }
    }

    @Autowired
    public void setText(String t) {
        txt = t;
    }
}

import java.util.*;
import javax.annotation.concurrent.GuardedBy;

public enum Category {
    ERROR("ERROR"), WARNING("WARNING");

    @GuardedBy("this")
    private static final Map<String, Category> mapping = new HashMap<>();

    static {
        Arrays.stream(Category.values()).forEach(unit -> mapping.put(unit.getValue(), unit));
    }

    @Getter(onMethod = @__({ @JsonValue }))
    private String value;

    Category(String value) {
        this.value = value;
    }

    @JsonCreator
    public static Category fromValue(String value) {
        return EnumUtil.getValue( mapping, value); // bad
    }
}

import net.jcip.annotations.GuardedBy;

class Issue576 {
    @GuardedBy("this")
    private String txt1;
    private String txt2;

    public void modifyTextSafe() {
        synchronized(this) {
            txt1 += "-appended";
            txt2 += "-appended";
        }
    }

    public boolean modifyTextUnSafe() {
      txt1 += "-appended"; // bad
      txt2 += "-appended"; // <-- false positive
    }

    static class InnerIssue {
        private String txt1;
        @GuardedBy("this")
        private String txt2;

        public void modifyTextSafe() {
          synchronized(this) {
            txt1 += "-appended";
            txt2 += "-appended";
          }
      }

      public boolean modifyTextUnSafe() {
        txt1 += "-appended"; // <-- false positive
        txt2 += "-appended"; // bad
      }
    }
}
